#[path = "solution.rs"]
mod solution;

use solution::{encode_banner, CellError};

fn encoded(text: &str) -> Vec<u8> {
    match encode_banner(text) {
        Ok(value) => value,
        Err(_) => panic!("expected successful encoding"),
    }
}

#[test]
fn accepts_empty_and_printable_ascii_boundaries() {
    assert!(encoded("").is_empty());
    assert_eq!(
        encoded(" ~A"),
        vec![0x20, 0xf3, 0x7e, 0xf3, b'A', 0xf3]
    );
}

#[test]
fn preserves_character_order_and_input() {
    let input = String::from("Legacy 09!?");
    let original = input.clone();
    let output = encoded(&input);

    let mut expected = Vec::new();
    for byte in input.bytes() {
        expected.push(byte);
        expected.push(0xf3);
    }
    assert_eq!(output, expected);
    assert_eq!(input, original);
}

#[test]
fn reports_utf8_byte_index_of_first_nonprintable_byte() {
    match encode_banner("AB\né") {
        Err(CellError::NonPrintable { byte_index }) => assert_eq!(byte_index, 2),
        _ => panic!("expected NonPrintable for newline"),
    }

    match encode_banner("AéZ") {
        Err(CellError::NonPrintable { byte_index }) => assert_eq!(byte_index, 1),
        _ => panic!("expected NonPrintable for non-ASCII UTF-8"),
    }

    match encode_banner("\u{7f}") {
        Err(CellError::NonPrintable { byte_index }) => assert_eq!(byte_index, 0),
        _ => panic!("expected NonPrintable for DEL"),
    }
}

#[test]
fn enforces_u16_character_limit() {
    let maximum = "A".repeat(u16::MAX as usize);
    let output = encoded(&maximum);
    assert_eq!(output.len(), (u16::MAX as usize) * 2);
    assert_eq!(&output[..4], &[b'A', 0xf3, b'A', 0xf3]);
    assert_eq!(&output[output.len() - 2..], &[b'A', 0xf3]);

    let too_long = "B".repeat(u16::MAX as usize + 1);
    match encode_banner(&too_long) {
        Err(CellError::TooLong) => {}
        _ => panic!("expected TooLong"),
    }
}

